// Package script describes the install-script installer's agent section
// (agent.script). It mirrors the environment schemas: one data-only type,
// validated and example-generated by the shared schema engine. The section
// is the installer's whole input — fields the install script does not consume
// (such as an image) do not exist here.
package script

import (
	"errors"
	"fmt"
	"regexp"

	"github.com/DataDog/datadog-agent/test/e2e-framework/cmd/internal/configschema"
	"go.yaml.in/yaml/v3"
)

// Config is what the official install script consumes.
type Config struct {
	Version      string            `yaml:"version" config:"required" pattern:"^[0-9]+[.][0-9]+[.][0-9]+$" example:"7.69.0" description:"Released agent version to install."`
	Config       string            `yaml:"config,omitempty" description:"Extra datadog.yaml configuration."`
	Integrations map[string]string `yaml:"integrations,omitempty" description:"conf.d folder name -> its conf.yaml contents."`
}

var integrationPattern = regexp.MustCompile(`^[a-zA-Z0-9_.-]+\.d$`)

// Rules checks what annotations cannot: integration folder names and the
// embedded agent config being valid YAML.
type Rules struct{}

func (Rules) Validate(c Config) error {
	for folder := range c.Integrations {
		if !integrationPattern.MatchString(folder) {
			return fmt.Errorf("integrations: %q is not a valid conf.d folder name", folder)
		}
	}
	if c.Config != "" {
		var out map[string]any
		if err := yaml.Unmarshal([]byte(c.Config), &out); err != nil {
			return errors.New("config: not valid YAML")
		}
	}
	return nil
}

// Schema is shared by the CLI adapters that validate, install and generate
// examples for the script installer.
var Schema = configschema.Must[Config](Rules{})
